//! Live NEAR testnet tests. Both are opt-in (`--ignored`).
//!
//! `testnet_rpc_read_only` only reads from testnet RPC.
//!
//! `testnet_payout_sent_and_finalized` moves real testnet NEAR. It needs an
//! OpenBao whose treasury key's implicit account the owner has funded:
//!
//!   OPENBAO_ADDR=... OPENBAO_TOKEN=<axom-signer token> \
//!   cargo test -p axom-signer --test testnet_live -- --ignored testnet_payout
//!
//! The recipient is a fresh implicit account generated by the test (the
//! worker brings their own key; Combox never holds it).

mod common;

use axom_core::near::PublicKey;
use axom_core::state::PayoutStatus;
use axom_hr::payouts;
use axom_signer::openbao::{OpenBaoTransit, TransitSigner};
use axom_signer::{SendResult, Signer};
use axom_tools::near_rpc::{testnet_rpc_url, JsonRpcNear, NearRpc, TxWait};
use common::*;
use ed25519_dalek::SigningKey;
use rust_decimal_macros::dec;
use sqlx::PgPool;

#[tokio::test]
#[ignore = "reads from NEAR testnet RPC"]
async fn testnet_rpc_read_only() {
    let near = JsonRpcNear::new(testnet_rpc_url());
    let pk = PublicKey(SigningKey::generate(&mut rand::rngs::OsRng).verifying_key().to_bytes());
    // A never-funded implicit account has no access key.
    assert_eq!(near.view_access_key(&pk.implicit_account(), &pk).await.unwrap(), None);
    // A probe for an unknown transaction answers at once with "unknown"
    // (a waiting query would block until the node's timeout instead).
    let fake_hash = bs58::encode([7u8; 32]).into_string();
    let started = std::time::Instant::now();
    assert_eq!(near.tx_status(&fake_hash, &pk.implicit_account(), TxWait::Probe).await.unwrap(), None);
    assert!(started.elapsed() < std::time::Duration::from_secs(20));
}

#[sqlx::test(migrator = "axom_core::MIGRATOR")]
#[ignore = "sends real testnet NEAR from a funded OpenBao treasury"]
async fn testnet_payout_sent_and_finalized(pool: PgPool) {
    let transit = OpenBaoTransit::from_env().expect("OPENBAO_ADDR and OPENBAO_TOKEN");
    let pk = transit.public_key().await.unwrap();
    let near = JsonRpcNear::new(testnet_rpc_url());
    let treasury = pk.implicit_account();
    assert!(near.view_access_key(&treasury, &pk).await.unwrap().is_some(), "fund the treasury {treasury} first");

    let f = Fixture::new(&pool, pk).await;
    // 1 task at 0.05 USD: well under the threshold.
    let (w, recipient) = f.ready_worker(&pool, dec!(0.05), 1).await;
    let id = f.payroll(&pool, w).await;
    assert_eq!(payouts::status(&pool, id).await.unwrap(), PayoutStatus::Approved);

    let s = Signer { pool: &pool, policy: &f.policy, cfg: &f.cfg, transit: &transit, near: &near, notify: &f.notify, intents: None };
    let out = s.send_payout(id, now()).await.unwrap();
    let SendResult::Sent { tx_hash } = out else { panic!("{out:?}") };
    println!("sent {treasury} -> {recipient}: https://testnet.nearblocks.io/txns/{tx_hash}");

    for _ in 0..30 {
        if s.finalize_sent(now()).await.unwrap().contains(&id) {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_secs(2)).await;
    }
    assert_eq!(payouts::status(&pool, id).await.unwrap(), PayoutStatus::Finalized);
}
